import { Component } from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';

interface TreeNode {
  id: string;
  label: string;
  locked?: boolean;
  children?: TreeNode[];
}

const TREE: TreeNode = {
  id: 'parent',
  label: 'Parent',
  children: [
    {
      id: 'child-1',
      label: 'Child 1',
      children: [
        { id: 'child-1-1', label: 'Child 1.1' },
        { id: 'child-1-2', label: 'Child 1.2' }
      ]
    },
    { id: 'child-2', label: 'Child 2' },
    { id: 'child-3', label: 'Child 3' },
    { id: 'child-4', label: 'Child 4', locked: true },
    { id: 'child-5', label: 'Child 5', locked: true }
  ]
};

// Only items with no children store a value. Every other checkbox is calculated from them.
const INITIAL_SELECTED: Record<string, boolean> = { 'child-5': true };

function leavesOf(node: TreeNode): TreeNode[] {
  return node.children ? node.children.flatMap((child) => leavesOf(child)) : [node];
}

const unlockedLeavesOf = (node: TreeNode) => leavesOf(node).filter((leaf) => !leaf.locked);

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [NgTemplateOutlet],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly tree = TREE;
  readonly unlockedLeaves = unlockedLeavesOf(TREE);

  selected = INITIAL_SELECTED;

  // Walking the tree keeps this order, whatever order the clicks came in.
  get selectedIds(): string[] {
    return this.unlockedLeaves.filter((leaf) => this.selected[leaf.id]).map((leaf) => leaf.id);
  }

  stateOf(node: TreeNode): { checked: boolean; indeterminate: boolean } {
    if (!node.children) {
      return { checked: !!this.selected[node.id], indeterminate: false };
    }
    // Locked items do not count, or the parent could never reach "all checked".
    const leaves = unlockedLeavesOf(node);
    const selectedCount = leaves.filter((leaf) => this.selected[leaf.id]).length;
    return {
      checked: selectedCount > 0 && selectedCount === leaves.length,
      indeterminate: selectedCount > 0 && selectedCount < leaves.length
    };
  }

  toggle(node: TreeNode): void {
    const value = !this.stateOf(node).checked;
    const next = { ...this.selected };
    for (const leaf of unlockedLeavesOf(node)) next[leaf.id] = value;
    this.selected = next;
  }

  reset(): void {
    this.selected = INITIAL_SELECTED;
  }
}

